const httpRes = $input.first().json;
const initialData = $('Validar y Preparar Prompt').item.json;
const conversationId = initialData.conversationId;
const model = $env.GEMINI_MODEL || 'gemini-1.5-flash';

const statusCode = Number(httpRes.statusCode || (httpRes.error ? 500 : 200));
const resBody = httpRes.body || httpRes;

// 1. Manejo de errores específicos según código HTTP
if (statusCode === 400) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'La solicitud enviada no es válida para el modelo de IA o el modelo configurado no existe.',
      provider: 'gemini',
      model,
      error: 'INVALID_REQUEST'
    }
  }];
}

if (statusCode === 401 || statusCode === 403) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'Error de autenticación con la API de Gemini. Verifica la GEMINI_API_KEY en N8N.',
      provider: 'gemini',
      model,
      error: 'AUTHENTICATION_ERROR'
    }
  }];
}

if (statusCode === 429) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'Límite de cuota excedido para el servicio de IA. Intenta de nuevo en unos minutos.',
      provider: 'gemini',
      model,
      error: 'RATE_LIMIT_EXCEEDED'
    }
  }];
}

if (statusCode >= 500 || httpRes.error) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'El servicio de Gemini no respondió a tiempo o no está disponible temporalmente.',
      provider: 'gemini',
      model,
      error: 'UPSTREAM_SERVER_ERROR'
    }
  }];
}

// 2. Extraer texto generado del formato oficial de Gemini
let generatedText = '';
try {
  const candidates = resBody.candidates || [];
  if (candidates.length > 0 && candidates[0].content && Array.isArray(candidates[0].content.parts)) {
    generatedText = candidates[0].content.parts
      .map((part) => (typeof part.text === 'string' ? part.text : ''))
      .join('\n')
      .trim();
  }
} catch (err) {
  generatedText = '';
}

if (!generatedText) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'El modelo de IA no generó ninguna respuesta de texto.',
      provider: 'gemini',
      model,
      error: 'EMPTY_RESPONSE'
    }
  }];
}

// 3. Respuesta exitosa normalizada
return [{
  json: {
    success: true,
    conversationId,
    message: generatedText,
    provider: 'gemini',
    model
  }
}];
